-- Раздел «Косметика»: каталог средств, который ведёт редакция (Directus → products)
create table if not exists products (
  id serial primary key,
  slug text unique not null,
  brand text not null,
  name text not null,
  type text not null,            -- glina, pasta, pomada, vosk, gel, pudra, sprej-s-morskoj-solyu, krem, tonik, shampun, maslo, balzam, vosk-dlya-usov, shampun-borody, konditsioner-borody, krem-dlya-britya, mylo-dlya-britya, do-britya, posle-britya
  branch text not null check (branch in ('volosy','boroda','britie')),
  hold smallint check (hold between 1 and 5),
  shine smallint check (shine between 1 and 5),
  base text,                     -- water | oil | clay | powder
  wash text,                     -- water | shampoo | hard
  hair_types text[] not null default '{}',     -- fine | normal | thick | curly
  lengths text[] not null default '{}',        -- 0-2 | 2-8 | 8-15 | 15+
  beard_lengths text[] not null default '{}',  -- 0-1 | 1-3 | 3-7 | 7+
  skin_types text[] not null default '{}',     -- dry | normal | oily | sensitive
  size text,
  description text not null,
  source_url text,                -- откуда взяты характеристики
  status text not null default 'published',
  sort int not null default 100,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now());
create index if not exists products_type on products(type) where status = 'published';


do $$ begin
  if exists (select 1 from information_schema.tables where table_name = 'directus_collections') then
      select 'products', 'spa', 'Косметика: средства для волос, бороды и бритья (раздел /kosmetika/)', 30, 'status', 'archived', 'published'
      where not exists (select 1 from directus_collections where collection = 'products');
      select 'products', f.field, f.iface, f.opts::json, null, f.s, f.w, f.note from (values
        ('branch', 'select-dropdown', '{"choices":[{"text":"Волосы","value":"volosy"},{"text":"Борода","value":"boroda"},{"text":"Бритьё","value":"britie"}]}', 3, 'half', 'Ветка раздела'),
        ('hold', 'slider', '{"minValue":1,"maxValue":5,"stepInterval":1}', 6, 'half', 'Фиксация 1–5 (пусто — не указана)'),
        ('shine', 'slider', '{"minValue":1,"maxValue":5,"stepInterval":1}', 7, 'half', 'Блеск: 1 матовый … 5 сильный'),
        ('base', 'select-dropdown', '{"choices":[{"text":"Водная","value":"water"},{"text":"Масляная","value":"oil"},{"text":"Глиняная","value":"clay"},{"text":"Пудра","value":"powder"}]}', 8, 'half', null),
        ('wash', 'select-dropdown', '{"choices":[{"text":"Водой","value":"water"},{"text":"Шампунем","value":"shampoo"},{"text":"С трудом","value":"hard"}]}', 9, 'half', 'Чем смывается'),
        ('hair_types', 'tags', '{"presets":["fine","normal","thick","curly"]}', 10, 'half', 'fine/normal/thick/curly'),
        ('lengths', 'tags', '{"presets":["0-2","2-8","8-15","15+"]}', 11, 'half', 'Длина волос сверху, см'),
        ('beard_lengths', 'tags', '{"presets":["0-1","1-3","3-7","7+"]}', 12, 'half', 'Длина бороды, см'),
        ('skin_types', 'tags', '{"presets":["dry","normal","oily","sensitive"]}', 13, 'half', 'Тип кожи (бритьё)'),
        ('status', 'select-dropdown', '{"choices":[{"text":"Опубликован","value":"published"},{"text":"Черновик","value":"draft"},{"text":"В архиве","value":"archived"}]}', 20, 'half', null),
        ('source_url', 'input', null, 21, 'full', 'Источник характеристик — обязательно для новых позиций')
      ) as f(field, iface, opts, s, w, note)
      where not exists (select 1 from directus_fields d where d.collection = 'products' and d.field = f.field);
  end if;
end $$;
select count(*) as products from products;